style.css:
/* ? READABLE PINK DISCORD THEME ? */

/* ===== BASE TEXT (SOFT PINK) ===== */
body, span, div, p, textarea, input {
    color: #ff7abf !important; /* soft rosy pink */
}

/* ===== MESSAGE TEXT ===== */
[class*="messageContent"],
[class*="markup"] {
    color: #ff7abf !important;
}

/* ===== USERNAMES (BRIGHT HOT PINK) ===== */
[class*="username"],
[class*="nameTag"],
[class*="headerText"],
[class*="roleColor"] {
    color: #ff1493 !important; /* hot pink */
    font-weight: 600;
}

/* ===== CHANNEL NAMES ===== */
[class*="channelName"],
[class*="name"] {
    color: #ff5cad !important;
}

/* ===== TIMESTAMPS ===== */
time,
[class*="timestamp"] {
    color: #ff9fd6 !important;
}

/* ===== LINKS ===== */
a, a * {
    color: #ff2fa7 !important;
}

/* ===== MENTIONS ===== */
[class*="mention"] {
    color: #ff1493 !important;
    background-color: rgba(255, 20, 147, 0.15) !important;
}

/* ===== INPUT BOX TEXT ===== */
textarea, input {
    color: #ff7abf !important;
}

/* ===== SIDEBARS / MEMBER LIST ===== */
nav *, aside * {
    color: #ff5cad !important;
}
